#!/bin/sh
# Generated by cargo volt. The implementation lives in the Rust host dependency.
set -eu
export PATH="$HOME/.cargo/bin:/opt/homebrew/bin:/usr/local/bin:$PATH"
MANIFEST="${VOLT_RUST_MANIFEST:-${SRCROOT:?Xcode project root required}/../Cargo.toml}"
META=$(mktemp "${TMPDIR:-/tmp}/volt-ios-metadata.XXXXXX")
trap 'rm -f "$META"' EXIT HUP INT TERM
# A fresh template has no lockfile. Resolve it once; subsequent builds are locked.
if [ -f "$(dirname "$MANIFEST")/Cargo.lock" ]; then
    cargo metadata --locked --format-version 1 --manifest-path "$MANIFEST" > "$META"
else
    cargo metadata --format-version 1 --manifest-path "$MANIFEST" > "$META"
fi
HOST=$(python3 - "$META" <<'PY'
import json,sys,os
m=json.load(open(sys.argv[1]));root=m['resolve']['root']
node=next(n for n in m['resolve']['nodes'] if n['id']==root)
ids={d['pkg'] for d in node['deps']}
h=[p for p in m['packages'] if p['id'] in ids and p['name']=='volt-ui-kit-mobile']
if len(h)!=1:raise SystemExit('Root app must depend directly on volt-ui-kit-mobile')
print(os.path.dirname(h[0]['manifest_path']))
PY
)
/bin/sh "$HOST/apple/build-rust.sh" "$META"
